CAL_FADE = (0.25, 0.5)            # calibration applies in full below 0.25 a week, fades out by 0.5 a week: the
                                  # under-forecast of slow styles is the same at every cut-off; above it the sign flips
                                  # cut-off to cut-off (timing, not a pattern), so the forecast is left alone
BAND_NAMES = ("Under 0.25 a week", "0.25-1 a week", "1-3 a week", "3-10 a week", "10+ a week")


def band_of(rate):
    return np.searchsorted(BAND_EDGES, np.asarray(rate, float), side="right")


def _nb_params(mu, alpha):
    """Negative binomial with mean mu and variance mu + alpha x mu^2 (alpha = 0 -> Poisson)."""
    mu = np.maximum(np.asarray(mu, float), 0)
    v = 1 + np.maximum(np.asarray(alpha, float), 0) * mu                     # variance / mean
    v = np.broadcast_to(v, mu.shape)
    pois = v < 1.001
    p = np.where(pois, 1.0, 1 / v)
    r = np.where(pois, np.inf, mu / np.maximum(v - 1, 1e-9))
    return mu, v, pois, p, r


def nb_p0(mu, alpha):
    """Chance of selling nothing."""
    mu, v, pois, p, r = _nb_params(mu, alpha)
    with np.errstate(invalid="ignore"):
        return np.where(pois, np.exp(-mu), np.exp(np.where(pois, 0, r) * np.log(p)))


def nb_quantile(mu, alpha, q):
    """Smallest whole number of units that covers q of outcomes. Exact recurrence up to mean 60, normal beyond."""
    mu, v, pois, p, r = _nb_params(mu, alpha)
    small = mu <= 60
    pm = np.where(small, nb_p0(np.where(small, mu, 0), alpha), 0.0)
    cdf = pm.copy()
    res = np.where(small & (cdf >= q), 0, -1)
    k = 0
    while ((res < 0) & small).any() and k < 400:
        pm = np.where(pois, pm * mu / (k + 1), pm * (k + np.where(pois, 0, r)) / (k + 1) * (1 - p))
        k += 1
        cdf = cdf + pm
        res = np.where((res < 0) & small & (cdf >= q), k, res)
    z = NormalDist().inv_cdf(q)
    big = np.ceil(mu + z * np.sqrt(v * mu))
    return np.where(mu <= 0, 0, np.where(small & (res >= 0), res, big)).astype(int)


def fit_calibration(pairs, bins=60):
    """Monotone map forecast -> mean actual, learned from backtest weeks (isotonic regression on forecast bins).
    The contest picks winners on units missed, which rewards forecasting ~0 for styles that sell now and then;
    this puts the level back to what such forecasts actually went on to sell."""
    f = np.concatenate([x for x, _ in pairs]); a = np.concatenate([x for _, x in pairs])
    order = np.argsort(f); f, a = f[order], a[order]
    idx = np.minimum(np.arange(len(f)) * bins // max(len(f), 1), bins - 1)    # equal-count bins
    blocks = []                                                                # [weight, sum actual, sum forecast]
    for i in range(bins):
        k = idx == i
        if k.any():
            blocks.append([float(k.sum()), float(a[k].sum()), float(f[k].sum())])
            while len(blocks) > 1 and blocks[-2][1] / blocks[-2][0] > blocks[-1][1] / blocks[-1][0]:
                last = blocks.pop()
                blocks[-1] = [x + y for x, y in zip(blocks[-1], last)]
    return np.array([b[2] / b[0] for b in blocks]), np.array([b[1] / b[0] for b in blocks])


def apply_calibration(f, cal):
    """Piecewise-linear between knots, proportional below the first; faded to the raw forecast over CAL_FADE;
    zero stays zero."""
    xs, ys = cal
    f = np.asarray(f, float)
    g = np.interp(f, xs, ys)
    g = np.where(f < xs[0], f * ys[0] / max(xs[0], 1e-9), g)
    w = np.clip((f - CAL_FADE[0]) / (CAL_FADE[1] - CAL_FADE[0]), 0, 1)
    return np.where(f > 0, (1 - w) * g + w * f, 0.0)


def poisson_mad(lam):
    """Expected |actual - rate| if the rate were known exactly (pure chance): 2 x rate x P(Y = floor(rate))."""
    lam = np.asarray(lam, float)
    fl = np.floor(lam)
    lg = np.array([math.lgamma(x + 1) for x in fl.ravel()]).reshape(lam.shape)
    with np.errstate(divide="ignore", invalid="ignore"):
        return np.where(lam > 0, 2 * np.exp(-lam + (fl + 1) * np.log(np.maximum(lam, 1e-300)) - lg), 0.0)


class RunLog:
    """Stage timings + plain-language event lines for the agent view."""

    def __init__(self):
        self.stages, self.events = [], []

    def now(self):
        return int(time.time() * 1000)

    def stage(self, key, agent):
        log = self

        class _S:
            def __enter__(s):
                s.t0 = log.now(); log.say(agent, "run", f"start · {key.replace('_', ' ')}", s.t0); return s

            def __exit__(s, *exc):
                log.stages.append({"stage": key, "agent": agent, "start": s.t0, "end": log.now(),
                                   "result": "FAILED" if exc[0] else "SUCCESS"})
                return False
        return _S()

    def say(self, agent, level, text, ts=None):
        self.events.append({"ts": ts or self.now(), "agent": agent, "level": level, "text": text})


def _num(df, cols):
    for c in cols:
        df[c] = pd.to_numeric(df[c], errors="coerce").fillna(0)
    return df


# ---------------- forecasting models (level per series from history up to t) ----------------
def _ma(y, k):
    return y[:, -k:].mean(axis=1)


def _ses(y, a=0.2):
    lvl = y[:, 0].astype(float)
    for t in range(1, y.shape[1]):
        lvl = a * y[:, t] + (1 - a) * lvl
    return lvl


def _croston_sba(y, a=0.1):
    n, T = y.shape
    z = np.zeros(n); p = np.ones(n); q = np.ones(n); init = np.zeros(n, bool)
    for t in range(T):
        nz = y[:, t] > 0
        first = nz & ~init
        z[first] = y[first, t]; p[first] = q[first]; init |= first
        upd = nz & ~first
        z[upd] = a * y[upd, t] + (1 - a) * z[upd]
        p[upd] = a * q[upd] + (1 - a) * p[upd]
        q = np.where(nz, 1, q + 1)
    return np.where(init, (1 - a / 2) * z / np.maximum(p, 1e-9), 0.0)


def _tsb(y, a=0.1, b=0.1):
    n, T = y.shape
    nzmask = y > 0
    prob = nzmask.mean(axis=1).astype(float)
    cnt = nzmask.sum(axis=1)
    z = np.where(cnt > 0, np.where(nzmask, y, 0).sum(axis=1) / np.maximum(cnt, 1), 0.0)
    for t in range(T):
        nz = nzmask[:, t]
        prob = b * nz + (1 - b) * prob
        z = np.where(nz, a * y[:, t] + (1 - a) * z, z)
    return prob * z


def level(y, method):
    return {"MA4": lambda: _ma(y, 4), "MA12": lambda: _ma(y, 12), "SES": lambda: _ses(y),
            "CROSTON_SBA": lambda: _croston_sba(y), "TSB": lambda: _tsb(y)}[method]()


def classify(y):
    """Syntetos-Boylan demand pattern over the last 52 weeks."""
    w = y[:, -52:]
    nz = w > 0
    cnt = nz.sum(axis=1)
    adi = np.where(cnt > 0, 52.0 / np.maximum(cnt, 1), np.inf)
    mean_nz = np.where(cnt > 0, np.nansum(np.where(nz, w, 0), axis=1) / np.maximum(cnt, 1), 0)
    sd_nz = np.sqrt(np.where(cnt > 0, np.nansum(np.where(nz, (w - mean_nz[:, None]) ** 2, 0), axis=1) / np.maximum(cnt, 1), 0))
    cv2 = np.where(mean_nz > 0, (sd_nz / np.maximum(mean_nz, 1e-9)) ** 2, 0)
    return np.select([cnt == 0, (adi < 1.32) & (cv2 < 0.49), adi < 1.32, cv2 < 0.49],
                     ["inactive", "smooth", "erratic", "intermittent"], "lumpy")



